        "lyric_excerpt": "后来，我总算学会了如何去爱。可惜你早已远去，消失在人海。后来终于在眼泪中明白，有些人一旦错过就不再。栀子花，白花瓣，落在我蓝色百褶裙上。爱你，你轻声说，我低下头闻见一阵芬芳。",
