        "row_key": "青柠",
        "lyric_excerpt": "可嗅到仲夏柠叶香，你莞尔的笑像。金色的柠檬味道，仿若青柠的悠扬，到达直通你心门的方向。冰镇可乐甜甜的芒果，一口拥抱全世界降落。有种诱惑，起个名字叫菠萝，看看你梦里有没有七彩虹。",
