        "row_key": "Virtual to LIVE",
        "lyric_excerpt": "总是过度紧张，在镜头前红了脸。迈着蹒跚脚步，不知道哪个明天梦想能够实现。不知跑了多久，依旧还在起跑线。每天的努力，仿佛都沉入睡眠。现实总是面对太多无奈和辛酸，此刻你和我虽然在世界两端，用我的歌声将你胸腔填满，心不再孤单。",
