        "row_key": "棠梨煎雪",
        "lyric_excerpt": "青鲤来时遥闻春溪声声碎，嗅得手植棠梨初发轻黄蕊。待小暑悄过，新梨渐垂，来邀东邻女伴撷花煎酒。依旧是，偏爱枕惊鸿二字，入梦的时节。烛火惺忪却可与她漫聊彻夜，早春暮春，酒暖花深，便好似一生心事只得一人来解。",
