        "row_key": "寄明月",
        "lyric_excerpt": "想化作庄周变成蝴蝶，驾青云穿过繁枝茂叶。纵然是群山层层叠叠，也无心在此流连停歇。将相思寄明月，期盼你能察觉。将你写作诗阙，送千里无邪。穿过了小巷后的古街，青墙旁你遥望夕阳斜，只因是不经意的一瞥，扰乱我思绪不舍昼夜。",
