        "row_key": "目的论",
        "lyric_excerpt": "若还记得黑白的梦，一场忘了结局的梦。写上句点的人将迫你成为永远的英雄。从此路线背离了一切，守护的人也消失不见。迎接泪水干涸的世界，独自去向的终点。屹立山顶那座雕像，不知究竟来自何方。无数夜晚他只静默地将那星空眺望。一句从未说出口的话，一双从未牵起过的手，只有泪水干涸不再流，思念何处是尽头。",
